<?php require_once 'config.php';require_login();$pageTitle='Minhas reservas';$s=db()->prepare('SELECT r.*,b.data,b.horario,b.duracao FROM reservas r JOIN baterias b ON b.id=r.bateria_id WHERE r.usuario_id=? ORDER BY r.data_reserva DESC LIMIT 5');$s->execute([user()['id']]);$reservas=$s->fetchAll();require 'includes/header.php'; ?><div class="page-top"><div><div class="eyebrow">Seu histórico na pista</div><h1 class="page-title">Minhas reservas</h1><p class="muted" style="font-size:13px">Exibindo suas cinco reservas mais recentes.</p></div><a class="btn" href="agendar.php">+ NOVA RESERVA</a></div><?php if($reservas): ?><div class="table-wrap"><table class="table"><thead><tr><th>Data da corrida</th><th>Horário</th><th>Duração</th><th>Participantes</th><th>Valor total</th><th>Reservado em</th></tr></thead><tbody><?php foreach($reservas as $r): ?><tr><td><?= date('d/m/Y',strtotime($r['data'])) ?></td><td><?= substr($r['horario'],0,5) ?></td><td><?= (int)$r['duracao'] ?> min</td><td><?= (int)$r['quantidade_participantes'] ?></td><td><strong>R$ <?= number_format($r['valor_total'],2,',','.') ?></strong></td><td><?= date('d/m/Y H:i',strtotime($r['data_reserva'])) ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="panel empty"><h3>Nenhuma reserva por enquanto</h3><p>Quando você reservar uma bateria, ela aparecerá aqui.</p><a class="btn" href="agendar.php">ESCOLHER BATERIA</a></div><?php endif; ?><?php require 'includes/footer.php'; ?>
